from connected_research_case import ResearchAuthor,present_case

a=ResearchAuthor('ai-7/35')
for old,new in [('Two 45-minute sessions.','Use the three-session teaching cycle above, with extra time as needed.'),('a20-case','a 20-case'),('with14','with 14'),('rate70','rate 70')]:
 if old in str(a.w):a.replace_text(old,new)
present_case(a,
 headline='Make the evidence easy to challenge in a presentation',
 purpose='Show the aggregate result, failure evidence and honest unknowns rather than only a best demonstration.',
 intro='A presentation should help the audience inspect the research, not merely admire an example. Start with the question and design, show the primary counts, then a failure, a limitation and a specific next question. When challenged about an untested device or condition, state the boundary and propose a test. A confident promise is not a substitute for the missing observations, and a proposed study must remain labelled not run.',
 contract=[['Presentation item','Complete supplied exercise contract'],['Main study','Fourteen passes among twenty cases'],['Main displayed item','One perfect output selected for demonstration'],['Supported main rate','14/20 = 70% under the supplied study summary'],['Other main cases','Six are not documented as passes; actual failure/unassessed breakdown not supplied here'],['Separate picture','Camera A only: ten correct of twelve photos'],['Original camera-B evidence','No records'],['Changed picture','One camera-B success displayed; selection/coverage not established'],['Independent challenge','Mobile performance asked about a desktop-only fictional project']],
 ledger=[['Main presentation step','Evidence-grounded version'],['Selected perfect output','Identify as one demonstration'],['Aggregate primary result','Fourteen of twenty, or seventy percent'],['Remaining six cases','Show actual failure/unassessed record when available; do not invent breakdown'],['Claim best output is representative','Not established by selecting it'],['Failure/limitation slide','Retain concrete supplied evidence and gaps'],['Next question','Propose a bounded test, with not-run status'],['Audience question outside scope','Locate evidence or state it is absent']],
 picture='The separate picture’s original project tests twelve camera-A photos and gets ten correct, approximately 83.333%. It contains no camera-B records, so the original study cannot establish performance on camera B. A proposed follow-up uses reserved camera-B cases with labels, source grouping and a fixed scoring rule. In the changed scenario, one camera-B success is displayed. That provides a single demonstration, not coverage or a broad reliability estimate; do not erase it or pretend it was part of the original study. Keep its selection status separate and continue to state what a planned representative condition test would need.',
 picture_table=[['Separate challenge evidence','Honest answer'],['Original camera A','10/12 correct ≈ 83.333% on those photos'],['Original camera B','No records; no supported rate'],['Later displayed B success','One demonstrated observation, selection/coverage unknown'],['Can claim broad camera-B reliability?','No'],['Proposed test','Reserved labelled B cases, grouping and fixed scoring'],['Proposed test status','Not run; no result invented'],['Remaining design issues','Sampling and uncertainty still need justification']],
 probes=[['Presentation audit','Checked interpretation'],['One perfect output','Demonstration, not the whole study'],['14/20 study passes','Seventy percent, not perfect performance'],['Six not documented as passes','Do not invent their exact missing/failure breakdown'],['No camera-B records originally','State scope; do not promise performance'],['One later camera-B success','Record separately, not a broad reliability estimate'],['Question about mobile after desktop-only test','Unknown in that fictional project'],['Future test proposed','Keep status not run'],['Honest limitation stated','Retain the primary result; do not hide it behind a demonstration']],
 investigation='Draft a six-part paper presentation: question, design, primary result, failure evidence, limitation and next question. For the main study show fourteen of twenty, seventy percent, and label the perfect output as a selected demonstration. Do not invent the other six cases’ exact statuses. Then rehearse the camera-B answer using the original ten/twelve camera-A evidence and separately labelled later demonstration. Outline a reserved-condition follow-up without claiming it ran. No audience message, model evaluation or new photo collection is performed. Reserve the independent mobile-versus-desktop question.',
 teacher_key='Main selected perfect output is one demonstration; aggregate rate 14/20 = 70%. Six cases are not documented as passes in this summary; do not invent the exact failure/unassessed breakdown. Retain actual negative-case records when supplied. Picture original camera A ten/twelve ≈ 83.333%, no B records. Later one B success is a demonstration with unknown coverage, not broad reliability. Propose reserved B cases with labels/grouping and fixed scoring, not a fabricated result. Independent fictional desktop-only project cannot answer mobile performance; say it was not tested and specify an appropriate reserved mobile follow-up with fixed criteria.',
 reference='A research presentation makes the evidence challengeable: question, design, primary result, failure, limitation and next question. Main one perfect output does not replace the fourteen/twenty study rate of 70%. Other six cases are not supplied as passes; exact failure/unassessed detail should come from actual records, not guesses. Separate original camera-A study has ten of twelve correct, about 83.333%, with no camera-B records. Answer the B challenge by stating that boundary and proposing reserved labelled B cases, grouping and fixed scoring. A later one-off B success is a demonstration, not broad condition coverage or a representative reliability estimate. Keep original and later records separate. Proposed work stays not run until evidence exists. Sampling and uncertainty remain relevant. A fictional desktop-only project similarly cannot establish mobile performance. The course performs a paper presentation rehearsal, not a live audience interaction or new study.',
 independent='Answer the fictional mobile challenge from the supplied desktop-only evidence and propose a specific unperformed follow-up.',
 image={'type':'image','src':'/api/resource/ai-7-35-evidence-boundary','alt':'Original project tests camera A only, ten correct of twelve photos, approximately eighty-three point three three three percent. Camera B originally has no records. A later one-camera-B success is a demonstration, not broad reliability. A reserved labelled camera-B test with fixed scoring is proposed, not run.','caption':'Keep measured scope, later demonstration and proposed evaluation as separate records. An honest unknown does not erase the original result.'})
